          <video ref={videoRef} autoPlay muted playsInline className={`w-full h-full object-cover ${isLive ? "block" : "hidden"} ${privacySettings.faceBlur ? "blur-[18px]" : ""}`} style={{ transform: "scaleX(-1)" }} />
