      {showRules && (<div className="absolute inset-0 z-[120] flex items-center justify-center p-4 bg-black/80"><div className="bg-[#121218] border border-[#E8C469] rounded-3xl p-5 w-full max-h-[85vh] overflow-y-auto"><h2 className="font-bold text-center">📜 RULES &amp; T&apos;s &amp; C&apos;s - 18+ 🔞</h2><div className="text-xs space-y-3 mt-3"><p><b>1. 18+ ONLY:</b> You must be 18+.</p><p><b>2. CONSENT:</b> No means no.</p><p><b>3. NO RECORDING:</b> No screenshots / sharing Private / DM / Locked.</p><p><b>4. NO REAL INFO:</b> No phone / address / ID / bank in chat.</p><p><b>5. NO ILLEGAL:</b> No minors, no non-consensual, no violence.</p><p><b>6. HOST RULES:</b> Host sets DM mode, DM price, VIP price.</p><p><b>7. COINS:</b> Coins for tips, unlocks, DM, VIP. Cashout min 50, weekly. 1 coin = R 0.27.</p><p><b>8. REPORT &amp; BLOCK:</b> Block / Report in 1 tap.</p><p><b>9. PRIVACY:</b> Watermark compulsory. Face Blur, Private Profile optional.</p><p><b>10. LIABILITY:</b> Users responsible for own content.</p></div><label className="flex gap-2 items-center text-xs mt-4"><input type="checkbox" checked={termsAccepted} onChange={(e) => { setTermsAccepted(e.target.checked); if (e.target.checked) setLS("loomi_terms", "yes"); }} className="w-4 h-4 accent-[#E8C469]" /> I accept Rules &amp; T&apos;s &amp; C&apos;s</label><button onClick={() => { setLS("loomi_terms", "yes"); setTermsAccepted(true); setShowTerms(false); setShowRules(false); }} className="w-full mt-3 bg-[#E8C469] text-black py-3 rounded-full font-bold">Accept &amp; Continue</button><button onClick={() => setShowRules(false)} className="w-full text-white/60 text-xs mt-2">Close</button></div></div>)}
